//! LLM prompt module — type `#: <prompt>` + Enter and atty replaces
//! the typed line with a shell command generated by the LLM behind
//! `$LLM_API_BASE` (falls back to `$OLLAMA_HOST`).
//!
//! Default prefix is `#: ` — `#` is bash/zsh's comment character, so
//! if the module is disabled or the call fails, the original typed
//! text is at worst silently no-op'd by the shell rather than
//! executed. Configurable.
//!
//! Flow:
//!   1. User types `#: list all zig files` + Enter.
//!   2. onInput detects the prefix on the committed line, returns
//!      `Action.replace = "\x15"` — the proxy sends Ctrl+U to the
//!      shell which kills its readline buffer (the `#: …` text
//!      disappears from screen). The Enter is NOT forwarded.
//!   3. Worker thread (spawned at attach) POSTs to
//!      `${api_base}/v1/chat/completions` (OpenAI-compatible — works
//!      with Ollama via its /v1 endpoint, llama.cpp's server, vLLM,
//!      and OpenAI proper). Response JSON is parsed for
//!      `choices[0].message.content`.
//!   4. `pollShellInput` (called once per tick by the proxy) surfaces
//!      the response bytes; the proxy writes them to pty.master and
//!      readline echoes them as if the user had typed them. User
//!      reviews, edits, hits Enter to run.
//!
//! API endpoint resolution:
//!   - `$LLM_API_BASE` if set (e.g. `http://localhost:11434/v1`)
//!   - else `$OLLAMA_HOST` if set (Ollama's native env; we suffix `/v1`
//!     automatically — Ollama's native API isn't OpenAI-compatible
//!     but its `/v1/*` mirror is)
//!   - else: module is inert
//! Auth: `$LLM_API_KEY` becomes a `Bearer <key>` header if set.

const std = @import("std");
const m = @import("../module.zig");
const keymap = @import("../keymap.zig");
const Osc133 = @import("../osc133.zig").Osc133;
const parse = @import("llm/parse.zig");
const types = @import("llm/types.zig");

extern "c" fn getenv(name: [*:0]const u8) ?[*:0]u8;

pub const Config = types.Config;

pub fn configure(comptime cfg: Config) type {
    return struct {
        pub const name = "llm";
        pub const config = cfg;

        /// Comptime-resolved system prompt. Honours an explicit
        /// `Config.system_prompt` override; otherwise picks the
        /// appropriate canned prompt for the with_explanation flag.
        const effective_system_prompt: []const u8 = if (cfg.system_prompt.len > 0)
            cfg.system_prompt
        else if (cfg.with_explanation)
            "You are an expert shell user. Given a natural-language description, reply with: (1) a SINGLE short sentence explaining what the command does, then a newline, then (2) a fenced block (```) containing EXACTLY ONE shell command on one line. Nothing else. No language tag on the fence. No prose after the closing fence."
        else
            "You are an expert shell user. Given a natural-language description, return EXACTLY ONE shell command that performs the task. Output ONLY the command on a single line. No markdown code fences. No explanation. No prefix or suffix text.";

        /// Comptime-built notification for inert mode. Mentions the
        /// configured env-var names (`cfg.api_base_env` /
        /// `api_base_fallback_env`) so users who renamed them see
        /// THEIR names rather than the upstream defaults, plus a
        /// hint to use the static `Config.api_base` if they'd
        /// rather skip env-var resolution entirely.
        const inert_error_msg: []const u8 = "no endpoint set — export $" ++
            cfg.api_base_env ++ " / $" ++ cfg.api_base_fallback_env ++
            ", or set Config.api_base in config.zig";

        /// Dialog-mode system prompt. Locks the model into a strict
        /// JSON-envelope response so we can parse `action` /
        /// `command` / `description` / `reason` reliably. The
        /// instruction set is deliberately terse — every line spent
        /// on prose costs tokens that should go to the user's
        /// task.
        const effective_dialog_system_prompt: []const u8 = if (cfg.dialog_system_prompt.len > 0)
            cfg.dialog_system_prompt
        else
            \\You are an interactive shell assistant. You receive a task and step-by-step OBSERVATIONS from previously executed commands. Reply ONLY with a JSON object on a single line. Allowed shapes:
            \\{"action":"exec","command":"<single-line shell command>","description":"<one short sentence>"}
            \\{"action":"done","reason":"<one short sentence>"}
            \\{"action":"question","question":"<short question>","options":["<opt1>","<opt2>"]}
            \\Never wrap the JSON in markdown fences. Never add prose around it. The command must be a single line, runnable as-is in the user's shell.
        ;

        /// Sentinel — used in `Shared.req_kind` to discriminate
        /// the legacy single-prompt path from the new dialog-loop
        /// path. Single-prompt uses `req_buf`+template; dialog
        /// uses the pre-built `body_buf`.
        const RequestKind = enum { single, dialog };

        const DialogState = enum {
            /// Not in a dialog. Either user hasn't entered AI mode
            /// or a previous dialog has been completed/cancelled.
            idle,
            /// Request is in flight (initial Alt+S, or a follow-up
            /// after an observation arrived). Worker is POSTing.
            generating,
            /// LLM has replied with `action=exec`; the suggested
            /// command is injected at the prompt and waiting for
            /// the user to press Enter (or cancel).
            suggesting,
            /// User hit Enter. Command bytes are on their way to
            /// the shell; we're waiting for OSC 133 `;C` to fire
            /// so we know the command actually started.
            executing,
            /// Between OSC 133 `;C` and `;D` — `onOutput` is
            /// appending bytes to `captured_output`.
            capturing_output,
            /// `;D` fired; observation is ready. Next `onTick` will
            /// push the observation as a turn and re-enter
            /// `.generating` with the follow-up request.
            observation_ready,
        };

        const DialogAction = enum { exec, question, done };

        const TurnKind = enum {
            /// Initial user task (`#: <task>` body).
            user,
            /// LLM's raw JSON reply for an exec step. Echoed back
            /// to the model verbatim on the next turn so the
            /// conversation stays self-consistent.
            assistant_exec,
            /// OSC 133 `;C` → `;D` captured output for the prior
            /// exec turn. Prefixed with `OBSERVATION:\n` when
            /// rendered into the request body.
            observation,
        };

        /// Conversation turn — heap-owned by the runtime (freed in
        /// `detach` and on cancel). Content length is bounded at
        /// `cfg.max_turn_bytes` so a runaway model can't bloat the
        /// process memory.
        const Turn = struct {
            kind: TurnKind,
            content: []u8,
        };

        /// Parsed dialog response. Stack-allocated; populated by
        /// `parseDialogResponse` from the raw assistant content.
        /// Unset fields stay len=0.
        const DialogResponse = struct {
            action: DialogAction = .done,
            command_buf: [cfg.max_response_bytes]u8 = undefined,
            command_len: usize = 0,
            description_buf: [256]u8 = undefined,
            description_len: usize = 0,
            reason_buf: [256]u8 = undefined,
            reason_len: usize = 0,

            fn command(self: *const DialogResponse) []const u8 {
                return self.command_buf[0..self.command_len];
            }
            fn description(self: *const DialogResponse) []const u8 {
                return self.description_buf[0..self.description_len];
            }
            fn reason(self: *const DialogResponse) []const u8 {
                return self.reason_buf[0..self.reason_len];
            }
        };

        const Shared = struct {
            mutex: std.Io.Mutex = .init,
            cv: std.Io.Condition = .init,
            /// Pending prompt set by onInput.
            req_buf: [cfg.max_prompt_bytes]u8 = undefined,
            req_len: usize = 0,
            req_pending: bool = false,
            /// Selected model INDEX for the pending request.
            /// Stored as an index (not a copy of the string) so we
            /// can't truncate long model names AND there's no
            /// length-zero sentinel confusion with an empty
            /// `cfg.models[i]` (which would be a user-config bug
            /// anyway). Filled by request-trigger sites (onInput /
            /// onAction) under the same mutex that sets req_pending.
            ///
            /// Out-of-range sentinel: `model_idx == usize.max`
            /// means "no models[] — fall back to cfg.model".
            /// Worker resolves the slice from `cfg.models` at
            /// read time. `cfg.*` strings are comptime/static so
            /// the resolved slice's backing storage lives forever
            /// — safe to use across the worker thread boundary
            /// without a copy.
            model_idx: usize = std.math.maxInt(usize),
            /// Monotonic counter — bumped on every prompt the proxy
            /// hands to the worker. The worker stamps each
            /// response with the generation it was serving; the
            /// proxy drops responses whose generation doesn't match
            /// the current `req_gen` (stale-response guard for the
            /// "user typed a new prompt while the previous one was
            /// still in flight" case).
            req_gen: u64 = 0,
            /// Latest LLM response. Worker writes both on success
            /// (res_len > 0) AND on failure (res_len = 0 with
            /// res_done = true) so pollShellInput can clear
            /// `in_flight` in both cases.
            res_buf: [cfg.max_response_bytes]u8 = undefined,
            res_len: usize = 0,
            /// Explanation text parsed from the response when
            /// `with_explanation` is set. Surfaced via
            /// `provideHintText` after pollShellInput consumes the
            /// command. `explanation_len == 0` means "no
            /// explanation parsed" (model didn't follow the format
            /// or `with_explanation` is off).
            explanation_buf: [512]u8 = undefined,
            explanation_len: usize = 0,
            /// Diagnostic message written by the worker when the
            /// request fails (connect error, HTTP non-2xx,
            /// unparseable response, or sanitiser stripped
            /// everything). Surfaced via `provideErrorText` (the
            /// muted-red + ⚠ notification slot, distinct from the
            /// hint slot used for explanations) so the user sees
            /// *why* the prompt produced no command. `error_len ==
            /// 0` means "no error to report".
            error_buf: [256]u8 = undefined,
            error_len: usize = 0,
            /// Generation of the prompt this response is for.
            res_gen: u64 = 0,
            /// True when the worker has finished serving the
            /// current request — success OR failure. Proxy
            /// consumes via pollShellInput and clears.
            res_done: bool = false,
            shutdown: bool = false,

            /// Discriminator for the worker — `.single` uses
            /// `req_buf` + the legacy template builder; `.dialog`
            /// POSTs `body_buf[0..body_len]` verbatim. Trigger
            /// sites set this under the same mutex as `req_pending`.
            req_kind: RequestKind = .single,
            /// The `req_kind` that was active when the worker
            /// started serving the current response. Stamped onto
            /// the response so pollShellInput knows whether to run
            /// the single-mode injection path or the dialog
            /// JSON-parse path — `req_kind` itself can be mutated
            /// by a fresh trigger between the worker writing
            /// `res_done = true` and the proxy reading it.
            res_kind: RequestKind = .single,
            /// Pre-built JSON request body for dialog mode. The
            /// trigger site (main thread) serializes the full
            /// conversation here so the worker doesn't need to
            /// know about turns / system prompts / history bounds.
            body_buf: [cfg.body_buf_bytes]u8 = undefined,
            body_len: usize = 0,
            /// Fixture-stub cursor. Used when `cfg.fixture_responses.len > 0`
            /// to deterministically replay canned responses without HTTP.
            /// Indexed under the shared mutex by the worker; wraps
            /// around modulo list length.
            fixture_idx: usize = 0,
        };

        pub const Runtime = struct {
            allocator: std.mem.Allocator,
            io: std.Io,
            shared: *Shared,
            /// Worker thread. `null` when the module is inert (no
            /// `$LLM_API_BASE` / `$OLLAMA_HOST` set) — saves the
            /// thread spawn for the common "module configured but
            /// no endpoint" case.
            thread: ?std.Thread,
            /// Resolved at attach. Empty = inert (no env var set).
            api_base: []u8 = &.{},
            /// Resolved at attach. Empty = no Authorization header.
            api_key: []u8 = &.{},
            /// Resolved shell name (basename of $SHELL or cfg.shell).
            shell: []u8 = &.{},
            /// Pre-built context line ("KEY=value, KEY2=value2") to
            /// append to the user message. Empty when no
            /// `context_env_vars` are configured or none of them
            /// are set in the environment. Owned by the runtime.
            context_blob: []u8 = &.{},
            /// Copy of the response surfaced via pollShellInput.
            /// Owned by the runtime; valid until the next poll.
            inject_buf: [cfg.max_response_bytes]u8 = undefined,
            inject_len: usize = 0,
            /// Latched explanation waiting to be surfaced via the
            /// next `provideHintText` call. One-shot: cleared on
            /// read so the hint row isn't re-painted forever.
            hint_buf: [512]u8 = undefined,
            hint_len: usize = 0,
            hint_pending: bool = false,
            /// Latched error-style notification waiting to be
            /// surfaced via the next `provideErrorText` call.
            /// Separate from `hint_buf` because the two slots have
            /// different styles + different precedence in the
            /// statusbar (errors win when both are active).
            err_buf: [512]u8 = undefined,
            err_len: usize = 0,
            err_pending: bool = false,
            /// Tracks whether we've already pushed the OSC 12
            /// cursor-colour change for the current prefix-typing
            /// session. Transition-driven (only emit on edge changes)
            /// so the terminal doesn't see redundant OSC traffic on
            /// every tick.
            cursor_signal_active: bool = false,
            /// True while a prompt is in flight.
            in_flight: bool = false,

            // ── AI mode state (the "explicit-actions" workflow) ──
            //
            // User types `#: ` (the prefix) → ai_mode_active flips
            // true → statusbar swaps to the AI hint → user presses
            // one of Alt+A / Alt+S / Alt+Shift+S to fire the
            // corresponding action. Enter in AI mode is swallowed
            // (no auto-fire). See `docs/llm-exec-mode-design.md`.
            ai_mode_active: bool = false,
            /// Index into `cfg.models[]` for the currently-selected
            /// model. Wraps around when `Alt+M` (`llm_exec_cycle_model`)
            /// fires. Initialised to 0 at attach (first entry is
            /// the default). Stays 0 forever when `cfg.models` is
            /// empty; in that case the legacy `cfg.model` is used
            /// instead.
            current_model_idx: usize = 0,
            /// Per-call format buffer for `statusText`. Used to
            /// inject the current model name into the AI hint
            /// when `cfg.models.len > 0` — `statusText` runs every
            /// render tick, but the returned slice only needs to
            /// outlive that single call, so a stable Runtime-owned
            /// buffer is the right shape. 256 bytes ≈ the typical
            /// statusbar width; longer hints are truncated by the
            /// statusbar's own clamp.
            status_buf: [256]u8 = undefined,
            /// Pending bytes for pollShellInput to surface. Used to
            /// route `\x15` (Ctrl+U) to the pty after onAction
            /// triggers a worker call — `onAction` can't synchronously
            /// modify the stdin path, so it queues the kill-line byte
            /// here and the next pollShellInput tick drains it
            /// AHEAD of the response. The pending injection always
            /// fits in 16 bytes (a Ctrl+U or a short ESC sequence).
            pending_injection: [16]u8 = undefined,
            pending_injection_len: usize = 0,

            // ── Dialog mode state (Alt+S) ────────────────────────
            //
            // Distinct from the single-prompt path. State machine
            // walks `idle → generating → suggesting → executing →
            // capturing_output → observation_ready → generating` in
            // a loop until the LLM says `action=done` (or the user
            // cancels). See `DialogState` for the per-state
            // semantics. Single-mode requests leave `dialog_state`
            // untouched at `.idle`.
            dialog_state: DialogState = .idle,
            /// Conversation history. Heap-allocated turns, FIFO
            /// truncation at `cfg.history_turns_max`. Freed
            /// individually as they age out, and bulk-freed on
            /// cancel / detach.
            turns: [cfg.history_turns_max]Turn = undefined,
            turns_len: usize = 0,
            /// Captured output between OSC 133 `;C` and `;D` for
            /// the most recent exec step. Filled in `onOutput`;
            /// drained in `onTick` (built into the next observation
            /// turn) and reset to 0.
            /// Heap-promoted to keep Runtime's stack footprint small —
            /// at 16 KB default this dominated the inline-Runtime size.
            /// Allocated in `attach`, freed in `detach`.
            captured_output: *[cfg.captured_output_bytes]u8,
            captured_output_len: usize = 0,
            /// True when `captured_output` was filled to the cap
            /// and tail bytes were dropped. Surfaced in the
            /// observation turn with a "[truncated]" suffix so the
            /// model knows the output was clipped.
            captured_truncated: bool = false,
            /// Per-runtime OSC 133 tracker. The proxy has its own
            /// global tracker for subprocess push/pop; we maintain
            /// a SECOND independent one here so we own the `;C` /
            /// `;D` edge stream + offsets and can capture the exact
            /// byte ranges between markers. Parsing cost is
            /// negligible — character-state-machine, no
            /// allocation.
            osc133_capture: Osc133 = undefined,
            /// Pending command suggested by the LLM, displayed at
            /// the prompt while in `.suggesting`. The user reviews,
            /// optionally edits, and presses Enter (or cancels).
            /// Lives separately from `inject_buf` because the
            /// single-mode path uses that buffer with different
            /// lifetime semantics.
            pending_command: [cfg.max_response_bytes]u8 = undefined,
            pending_command_len: usize = 0,
            /// Description of the pending command (model's
            /// `description` field). Surfaced as the hint above
            /// the bar while in `.suggesting`. 256 bytes ≈ enough
            /// for a one-line summary; longer descriptions are
            /// truncated.
            pending_description: [256]u8 = undefined,
            pending_description_len: usize = 0,
            /// Raw JSON response body for the current exec step.
            /// Owned by `pollShellInput` (where the JSON is
            /// parsed); appended verbatim as an `assistant_exec`
            /// turn so the conversation echoes back what the LLM
            /// actually emitted.
            /// Heap-promoted alongside `captured_output` — same
            /// rationale (4 KB default off the inline Runtime).
            last_assistant_json: *[cfg.max_response_bytes]u8,
            last_assistant_json_len: usize = 0,
        };

        pub fn attach(allocator: std.mem.Allocator, io: std.Io) !Runtime {
            const shared = try allocator.create(Shared);
            shared.* = .{};
            errdefer allocator.destroy(shared);

            // Heap-promote the two biggest inline buffers off
            // Runtime so the stack footprint stays small even with
            // generous comptime config sizes (default totals: 16 KB
            // capture + 4 KB JSON).
            const captured_output = try allocator.create([cfg.captured_output_bytes]u8);
            errdefer allocator.destroy(captured_output);
            const last_assistant_json = try allocator.create([cfg.max_response_bytes]u8);
            errdefer allocator.destroy(last_assistant_json);

            // Resolve env vars at attach time so the worker doesn't
            // have to re-read them per request.
            const api_base = try resolveApiBase(allocator);
            errdefer allocator.free(api_base);
            const api_key = try resolveEnv(allocator, cfg.api_key_env);
            errdefer allocator.free(api_key);
            const shell_name = try resolveShell(allocator);
            errdefer allocator.free(shell_name);
            const context_blob = try resolveContextEnv(allocator);
            errdefer allocator.free(context_blob);

            // Skip the worker thread entirely in inert mode. With
            // no endpoint we'll never call the worker, and onInput
            // / pollShellInput already short-circuit on
            // `api_base.len == 0`.
            const thread: ?std.Thread = if (api_base.len == 0)
                null
            else
                try std.Thread.spawn(.{}, worker, .{ shared, io, allocator, api_base, api_key, shell_name, context_blob });

            return .{
                .allocator = allocator,
                .io = io,
                .shared = shared,
                .thread = thread,
                .api_base = api_base,
                .api_key = api_key,
                .shell = shell_name,
                .context_blob = context_blob,
                .osc133_capture = Osc133.init(allocator),
                .captured_output = captured_output,
                .last_assistant_json = last_assistant_json,
            };
        }

        pub fn detach(rt: *Runtime, io: std.Io) void {
            freeTurns(rt);
            rt.osc133_capture.deinit();
            // Heap-promoted Runtime buffers are owned by the main
            // thread alone — the worker reaches into `Shared`, not
            // these — so they can be freed even on the
            // worker-still-running path that intentionally leaks
            // worker-owned state below.
            rt.allocator.destroy(rt.captured_output);
            rt.allocator.destroy(rt.last_assistant_json);
            if (rt.thread) |t| {
                {
                    rt.shared.mutex.lockUncancelable(io);
                    defer rt.shared.mutex.unlock(io);
                    rt.shared.shutdown = true;
                    rt.shared.cv.signal(io);
                }
                // Detach instead of join. The worker may be blocked
                // inside a slow HTTP request (unreachable endpoint
                // / OS TCP timeout) and won't observe `shutdown`
                // until the request returns — joining would hang
                // atty's exit for tens of seconds. The OS reaps
                // the thread when the process exits; we deliberately
                // leak the heap allocations the worker still
                // references (shared / api_base / api_key / shell /
                // context_blob) because freeing them here is a
                // use-after-free race. detach() is the documented
                // escape hatch for exactly this "fire-and-forget at
                // process exit" case.
                t.detach();
                return;
            }
            // Inert mode (no worker spawned): safe to clean up
            // synchronously.
            rt.allocator.destroy(rt.shared);
            rt.allocator.free(rt.api_base);
            rt.allocator.free(rt.api_key);
            rt.allocator.free(rt.shell);
            rt.allocator.free(rt.context_blob);
        }

        // ---- env / config helpers ----------------------------------------

        fn resolveApiBase(allocator: std.mem.Allocator) ![]u8 {
            // Priority order: static cfg → primary env → fallback env
            // (with /v1 suffixing for the Ollama path). Normalize a
            // single trailing slash on each — `doRequest` appends
            // `/chat/completions`, so a base ending in `/` would
            // produce `…//chat/completions`, which some
            // proxies/routers reject or normalize inconsistently.
            // Strip exactly one slash; we don't want to collapse
            // intentional multi-segment paths.
            if (cfg.api_base.len > 0) {
                const s = cfg.api_base;
                const trimmed = if (s[s.len - 1] == '/') s[0 .. s.len - 1] else s;
                return allocator.dupe(u8, trimmed);
            }
            if (envValue(cfg.api_base_env)) |s| {
                const trimmed = if (s.len > 0 and s[s.len - 1] == '/') s[0 .. s.len - 1] else s;
                return allocator.dupe(u8, trimmed);
            }
            if (envValue(cfg.api_base_fallback_env)) |s| {
                const trimmed = if (s.len > 0 and s[s.len - 1] == '/') s[0 .. s.len - 1] else s;
                if (std.mem.endsWith(u8, trimmed, "/v1")) return allocator.dupe(u8, trimmed);
                return std.fmt.allocPrint(allocator, "{s}/v1", .{trimmed});
            }
            return allocator.dupe(u8, "");
        }

        fn resolveEnv(allocator: std.mem.Allocator, env_name: []const u8) ![]u8 {
            if (envValue(env_name)) |s| return allocator.dupe(u8, s);
            return allocator.dupe(u8, "");
        }

        /// Build the env-var context blob from `cfg.context_env_vars`.
        /// Format: `KEY=value, KEY2=value2` — single line, comma-
        /// separated, only entries whose env var is set and non-
        /// empty are included. Returns an empty slice when no
        /// matches are found so the worker can append-and-no-op.
        fn resolveContextEnv(allocator: std.mem.Allocator) ![]u8 {
            if (cfg.context_env_vars.len == 0) return allocator.dupe(u8, "");
            var allocating: std.Io.Writer.Allocating = .init(allocator);
            errdefer allocating.deinit();
            var first = true;
            for (cfg.context_env_vars) |env_name| {
                const v = envValue(env_name) orelse continue;
                if (!first) try allocating.writer.writeAll(", ");
                first = false;
                try allocating.writer.print("{s}=", .{env_name});
                try writeSanitizedEnvValue(&allocating.writer, v);
            }
            return allocating.toOwnedSlice();
        }

        /// Write an env-var value into the context blob writer with
        /// any whitespace / control bytes collapsed to a single
        /// space. Env values can legally contain newlines, carriage
        /// returns, tabs, NUL — without sanitisation a value with
        /// `\n` would split the "one-line" context across multiple
        /// lines in the JSON-encoded prompt body, confusing the
        /// model and risking prompt-injection-shaped behaviours.
        /// Per-value cap of 256 bytes after sanitisation; longer
        /// values truncate with no ellipsis (the context is a
        /// hint, not authoritative).
        fn writeSanitizedEnvValue(w: *std.Io.Writer, v: []const u8) !void {
            const max_per_value = 256;
            var written: usize = 0;
            var last_was_space = false;
            for (v) |b| {
                if (written >= max_per_value) break;
                if (b < 0x20 or b == 0x7F or b == ' ' or b == '\t' or b == '\r' or b == '\n') {
                    if (last_was_space) continue;
                    try w.writeByte(' ');
                    written += 1;
                    last_was_space = true;
                    continue;
                }
                try w.writeByte(b);
                written += 1;
                last_was_space = false;
            }
        }

        fn resolveShell(allocator: std.mem.Allocator) ![]u8 {
            if (cfg.shell) |s| return allocator.dupe(u8, s);
            if (envValue("SHELL")) |s| {
                if (std.mem.lastIndexOfScalar(u8, s, '/')) |i| return allocator.dupe(u8, s[i + 1 ..]);
                return allocator.dupe(u8, s);
            }
            return allocator.dupe(u8, "sh");
        }

        fn envValue(env_name: []const u8) ?[]const u8 {
            // Null-terminated lookup via libc — we don't want to
            // walk std.os.environ ourselves.
            var name_buf: [128]u8 = undefined;
            if (env_name.len >= name_buf.len) return null;
            @memcpy(name_buf[0..env_name.len], env_name);
            name_buf[env_name.len] = 0;
            const v = getenv(@ptrCast(&name_buf)) orelse return null;
            const s = std.mem.sliceTo(v, 0);
            if (s.len == 0) return null;
            return s;
        }

        // ---- hooks --------------------------------------------------------

        pub fn onInput(rt: *Runtime, ctx: *m.Context, input: []const u8) m.Error!m.Action {
            // Observe the line state to maintain `ai_mode_active`.
            // Runs on EVERY keystroke (cheap — just a prefix
            // check). When the user types `#: ` the flag flips to
            // true; the statusText hook reads the flag and swaps
            // the bar's text to the AI mode hint. Backspacing the
            // prefix flips it back. Mode is observational only;
            // the action keys (Alt+A / Alt+S / Alt+Shift+S) are
            // what actually trigger LLM work — see `onAction`
            // below + `docs/llm-exec-mode-design.md`.
            rt.ai_mode_active = std.mem.startsWith(u8, ctx.line.current(), cfg.prefix);

            const is_enter = blk: {
                for (input) |b| if (b == 0x0D or b == 0x0A) break :blk true;
                break :blk false;
            };
            if (!is_enter) return .forward;

            // Same lookup pattern as guardrail: applyInput already
            // ran, so the line we want is in lastCommitted.
            const line = ctx.line.lastCommitted() orelse ctx.line.current();
            if (!std.mem.startsWith(u8, line, cfg.prefix)) return .forward;

            // Enter in AI mode is intentionally a no-op for
            // dialog/auto modes (you must explicitly pick an action
            // key — security against accidental LLM calls). For the
            // single-shot single-prompt path, we KEEP the legacy
            // `#:<Enter>` trigger here so existing user muscle
            // memory still works alongside the new `Alt+A`. Both
            // routes call `triggerSinglePrompt` so the behaviour is
            // identical.
            const result = triggerSinglePrompt(rt, ctx, line, .replace_commit_on_enter);
            // Mirror the Alt+A eager-clear of `ai_mode_active`.
            // The shell wipes the line via the returned
            // `.replace_commit = "\x15"`, so the prefix is gone
            // from line_state on the next keystroke. Clearing
            // ai_mode_active now means the verbose statusbar hint
            // disappears immediately, not on the next keypress —
            // same flicker-free behaviour the Alt+A path has.
            // Gated on api_base.len for the same reason: inert
            // mode keeps the user in AI mode so they can fix
            // config + retry.
            if (rt.api_base.len != 0 and result == .replace_commit) {
                rt.ai_mode_active = false;
            }
            return result;
        }

        /// Dispatch site for the keymap actions `llm_exec_*`. The
        /// proxy calls this for every binding match; the module
        /// gates each action on `ai_mode_active` (i.e. the user is
        /// currently inside an AI prompt — the line starts with
        /// `#: `). Outside AI mode, the actions no-op silently so
        /// stray Alt-key presses don't surprise the user.
        ///
        /// **Returns** true when the action was handled (proxy
        /// swallows the binding bytes); false when not (proxy
        /// lets the bytes flow through to readline / the inner
        /// program — so e.g. Alt+a outside AI mode still hits
        /// readline's "set-mark" or whatever the user has bound
        /// there).
        ///
        /// Per-action behaviour:
        /// - `llm_exec_single`: same as `#:<Enter>` — kick the
        ///   worker with the current line body, queue Ctrl+U for
        ///   the next `pollShellInput` tick to wipe the typed
        ///   `#: …` text. The LLM response gets injected when it
        ///   lands.
        /// - `llm_exec_dialog` / `_auto`: TODO (dialog state
        ///   machine not yet wired). For now, latch a
        ///   "coming soon" hint so the user sees feedback.
        /// - `llm_exec_cycle_model`: rotates `current_model_idx`
        ///   through the configured list. TODO until the model
        ///   list config arrives.
        /// - `llm_exec_toggle_help`: TODO — help overlay not yet
        ///   wired.
        /// - `llm_exec_cancel`: clears any in-flight state, bumps
        ///   the worker's req_gen so a late response is dropped,
        ///   wipes the typed prompt via Ctrl+U injection, clears
        ///   ai_mode_active. Works outside AI mode too (drains
        ///   any leftover state).
        pub fn onAction(rt: *Runtime, ctx: *m.Context, action: keymap.Action) m.Error!bool {
            switch (action) {
                .llm_exec_single => {
                    if (!rt.ai_mode_active) return false;
                    const line = ctx.line.current();
                    const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
                    // Empty body — user pressed Alt+A right after
                    // typing `#: ` with no task. Info hint, no
                    // worker call, no Ctrl+U; user keeps typing.
                    if (body.len == 0) {
                        latchHint(rt, "type your task after `#: ` then press Alt+A");
                        return true; // consumed (we displayed feedback)
                    }
                    // Over-length body — explicit hint instead of
                    // a silent no-op. Without this, `trigger
                    // SinglePrompt`'s internal `body.len >
                    // max_prompt_bytes` branch would return
                    // `.forward` without queuing Ctrl+U or
                    // latching feedback, and the Alt+A press
                    // would visibly do nothing.
                    if (body.len > cfg.max_prompt_bytes) {
                        latchHint(rt, "prompt too long — shorten the task and try again");
                        return true;
                    }
                    _ = triggerSinglePrompt(rt, ctx, line, .queue_pending_injection);
                    // Clear AI mode immediately — the line is
                    // about to be wiped by Ctrl+U, so the prefix
                    // won't match next time `onInput` recomputes
                    // the flag. Without this, the verbose hint
                    // would linger in the statusbar until the
                    // user's next keystroke.
                    //
                    // BUT only when the worker actually got the
                    // prompt. In inert mode (no api_base resolved
                    // at attach), `triggerSinglePrompt` latches
                    // the "no endpoint" error and returns without
                    // queuing Ctrl+U — so the typed `#: …` text
                    // stays on the prompt. If we cleared
                    // ai_mode_active here, the very next
                    // keystroke would see the prefix still on
                    // line_state.current() and flip the flag
                    // back to true, producing a visible one-
                    // tick flicker in the statusbar hint. Inert
                    // mode is the user's signal to fix their
                    // config + re-try, so leave them IN AI mode
                    // — the error notification points at the
                    // fix.
                    if (rt.api_base.len != 0) rt.ai_mode_active = false;
                    return true;
                },
                .llm_exec_dialog => {
                    if (!rt.ai_mode_active) return false;
                    const line = ctx.line.current();
                    const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
                    if (body.len == 0) {
                        latchHint(rt, "type your task after `#: ` then press Alt+S");
                        return true;
                    }
                    if (body.len > cfg.max_prompt_bytes) {
                        latchHint(rt, "prompt too long — shorten the task and try again");
                        return true;
                    }
                    if (rt.api_base.len == 0) {
                        latchErr(rt, inert_error_msg);
                        return true;
                    }
                    // Dialog mode requires OSC 133 — without `;C` /
                    // `;D` we can't tell when the shell finished
                    // running each step's command. Detect missing
                    // integration by checking whether ANY marker has
                    // arrived since the runtime attached. Single mode
                    // (Alt+A) doesn't have this requirement.
                    if (!rt.osc133_capture.active) {
                        latchErr(rt, "exec mode needs OSC 133 — run `eval \"$(atty init bash)\"` or use Alt+A");
                        return true;
                    }
                    // Stage the first user turn from the typed body.
                    const initial = rt.allocator.dupe(u8, body) catch {
                        latchErr(rt, "out of memory starting dialog");
                        return true;
                    };
                    pushTurn(rt, .user, initial) catch {
                        rt.allocator.free(initial);
                        latchErr(rt, "out of memory starting dialog");
                        return true;
                    };

                    fireDialogRequest(rt, ctx) catch |err| {
                        abortDialog(rt, ctx, switch (err) {
                            error.BodyTooLarge => "dialog body too large for buffer — increase Config.body_buf_bytes",
                            error.OutOfMemory => "out of memory firing dialog request",
                            else => "internal error firing dialog request",
                        });
                        return true;
                    };
                    // Wipe the `#: …` typed text — about to be
                    // replaced by the suggested command on response.
                    queueInjection(rt, "\x15");
                    rt.ai_mode_active = false;
                    return true;
                },
                .llm_exec_auto => {
                    if (!rt.ai_mode_active) return false;
                    latchHint(rt, "auto exec coming in a follow-up PR — use Alt+S for now");
                    return true;
                },
                .llm_exec_cycle_model => {
                    if (!rt.ai_mode_active) return false;
                    if (cfg.models.len == 0) {
                        // Single-model config — nothing to cycle.
                        // Honest feedback so users know why
                        // Alt+M didn't do anything.
                        latchHint(rt, "single-model config — set `models = &.{ ... }` to cycle");
                        return true;
                    }
                    rt.current_model_idx = (rt.current_model_idx + 1) % cfg.models.len;
                    // Latch a one-line hint with the new pick so
                    // the user sees confirmation. Statusbar AI
                    // hint will also reflect the new model on the
                    // next tick (statusText appends the current
                    // pick when models.len > 0).
                    const new_model = cfg.models[rt.current_model_idx];
                    var msg_buf: [128]u8 = undefined;
                    const msg = std.fmt.bufPrint(&msg_buf, "model: {s}", .{new_model}) catch new_model;
                    latchHint(rt, msg);
                    return true;
                },
                .llm_exec_toggle_help => {
                    if (!rt.ai_mode_active) return false;
                    // Help overlay — surface state that isn't in
                    // the verbose AI hint: current model + how
                    // many alternates are in the cycle, the
                    // resolved endpoint, and a pointer at the
                    // single way to actually cancel. Limited to
                    // ~256 bytes; truncates gracefully on narrow
                    // terms.
                    //
                    // BOTH cycle_info and the final message live in
                    // `buf` so the cycle slice doesn't escape a
                    // nested scope (a previous draft put cycle_info's
                    // backing array inside a `blk` expression — the
                    // slice outlived the array, classic stack-use-
                    // after-scope hazard). One outer buffer, two
                    // bufPrint calls into disjoint subslices.
                    var buf: [256]u8 = undefined;
                    const current: []const u8 = if (cfg.models.len > 0)
                        cfg.models[rt.current_model_idx]
                    else
                        cfg.model;
                    // Cycle info lives in the first 32 bytes of buf.
                    const cycle_info: []const u8 = if (cfg.models.len > 1)
                        std.fmt.bufPrint(buf[0..32], " ({d}/{d})", .{ rt.current_model_idx + 1, cfg.models.len }) catch ""
                    else
                        "";
                    const endpoint: []const u8 = if (rt.api_base.len > 0) rt.api_base else "(inert — no endpoint)";
                    // Message goes into the remaining bytes. cycle_info
                    // is referenced before its underlying storage is
                    // overwritten — bufPrint copies the formatted
                    // string verbatim, so this read-then-write order
                    // is safe.
                    const msg = std.fmt.bufPrint(buf[32..], "model: {s}{s} · endpoint: {s} · Ctrl+Shift+X cancel · Ctrl+Shift+I incognito", .{ current, cycle_info, endpoint }) catch {
                        // Truncated; render at least the model name.
                        latchHint(rt, current);
                        return true;
                    };
                    latchHint(rt, msg);
                    return true;
                },
                .llm_exec_cancel => {
                    // Only claim consumed when there's actual
                    // state to clear — otherwise the user's
                    // Ctrl+Shift+X bytes flow through to any
                    // inner program (vim / emacs / less) that
                    // might bind them. Without this gate every
                    // stray Ctrl+Shift+X in a normal shell got
                    // eaten by atty.
                    const dialog_active = rt.dialog_state != .idle;
                    const had_work = rt.in_flight or rt.ai_mode_active or rt.pending_injection_len > 0 or dialog_active;
                    if (!had_work) return false;

                    // Dialog cancel funnels through dialogReset
                    // which handles the req_gen bump + turn
                    // cleanup + state machine reset. Always wipe
                    // the prompt — the suggested command (or
                    // `#: …` prefix) is typically visible.
                    dialogReset(rt, ctx);
                    queueInjection(rt, "\x15");
                    // Reset line_state to match the post-Ctrl+U
                    // shell state. The injection wipes the shell's
                    // readline buffer but `applyInput` doesn't see
                    // it (injections flow atty→shell, while
                    // line_state observes shell→user / user→shell);
                    // without this reset, line_state would keep the
                    // pre-cancel `#: …` prefix and the next Enter
                    // would re-fire the legacy single-shot
                    // trigger in `onInput`.
                    ctx.line.reset();
                    rt.ai_mode_active = false;
                    return true;
                },
                else => return false, // not our action
            }
        }

        /// Trigger source — affects whether we return `.replace_commit`
        /// (the legacy `#:<Enter>` path) or queue the Ctrl+U on
        /// `pending_injection` (the `Alt+A` action path, which has no
        /// return-value channel to the proxy).
        const TriggerKind = enum { replace_commit_on_enter, queue_pending_injection };

        fn triggerSinglePrompt(
            rt: *Runtime,
            ctx: *m.Context,
            line: []const u8,
            kind: TriggerKind,
        ) m.Action {
            const body = std.mem.trim(u8, line[cfg.prefix.len..], " \t");
            if (body.len == 0 or body.len > cfg.max_prompt_bytes) return .forward;
            if (rt.api_base.len == 0) {
                // Inert mode — the user has the module configured
                // but no endpoint resolved at attach time. Latch
                // the muted-red ⚠ error notification.
                latchErr(rt, inert_error_msg);
                return .forward;
            }

            // Resolve the model INDEX to stage. Worker reads
            // `cfg.models[idx]` directly when idx is in-range, else
            // falls back to `cfg.model`. Out-of-range
            // `current_model_idx` (shouldn't happen — Alt+M wraps —
            // but defensive) clamps to 0.
            const idx_to_send: usize = if (cfg.models.len == 0)
                std.math.maxInt(usize) // sentinel: "no list, use cfg.model"
            else if (rt.current_model_idx < cfg.models.len)
                rt.current_model_idx
            else
                0;

            // Hand the prompt to the worker. Same locking + req-gen
            // bump as before — see the original onInput comment for
            // the stale-response guard rationale.
            rt.shared.mutex.lockUncancelable(ctx.io);
            defer rt.shared.mutex.unlock(ctx.io);
            @memcpy(rt.shared.req_buf[0..body.len], body);
            rt.shared.req_len = body.len;
            rt.shared.model_idx = idx_to_send;
            rt.shared.req_kind = .single;
            rt.shared.req_pending = true;
            rt.shared.req_gen +%= 1;
            rt.shared.res_done = false;
            rt.shared.res_len = 0;
            rt.shared.cv.signal(ctx.io);
            rt.in_flight = true;

            switch (kind) {
                .replace_commit_on_enter => return .{ .replace_commit = "\x15" },
                .queue_pending_injection => {
                    // onAction can't return an Action that the
                    // proxy injects. Queue the Ctrl+U on
                    // `pending_injection` so the next
                    // pollShellInput tick (~50ms) surfaces it
                    // ahead of any LLM response. Same visible
                    // effect: line gets wiped, response gets
                    // injected when ready.
                    queueInjection(rt, "\x15");
                    return .forward;
                },
            }
        }

        /// OSC 133 output capture for dialog mode. Always feeds the
        /// per-runtime tracker (so `osc133_capture.active` is current
        /// the moment the user hits Alt+S); state transitions and
        /// byte capture only fire while a dialog is mid-execution.
        ///
        /// We use a SECOND osc133 instance independent of the proxy's
        /// global one because the proxy's tracker is consumed
        /// destructively by `drainEdges()` — sharing it would race
        /// the subprocess-stack consumer.
        pub fn onOutput(rt: *Runtime, ctx: *m.Context, output: []const u8) m.Error!void {
            _ = ctx;
            rt.osc133_capture.feed(output);
            const edges = rt.osc133_capture.drainEdges();

            // Outside dialog execution, the only reason to feed was
            // to keep `active` tracking up to date. No state work
            // needed when we're idle/generating/suggesting (the
            // command hasn't run yet, so `;C` hasn't fired).
            const tracking = rt.dialog_state == .executing or rt.dialog_state == .capturing_output;
            if (!tracking) return;

            // `edgeOffset(i)` returns the byte index of the
            // marker's TERMINATOR (BEL `0x07` or ST's `\`), not of
            // its leading ESC. To slice OUT the OSC 133 marker from
            // the captured observation, we advance the capture
            // cursor PAST the terminator on `cmd_start`, and on
            // `cmd_end` we walk backwards from the terminator to
            // find the ESC that began the marker — capturing only
            // the bytes BETWEEN markers.
            //
            // Multi-feed caveat: if a closing marker's ESC arrives
            // in a different feed than its BEL, the backwards
            // search won't find it inside this `output` slice and
            // we conservatively capture up to the BEL position
            // (over-capturing the marker prefix into the
            // observation). This isn't optimal but it's bounded
            // (≤ marker size) and uncommon — shells flush whole
            // OSC sequences atomically in practice.
            var cursor: u32 = 0;
            var capturing = rt.dialog_state == .capturing_output;
            for (edges, 0..) |edge, i| {
                const offset = rt.osc133_capture.edgeOffset(i);
                switch (edge) {
                    .cmd_start => {
                        // Stray `;C` mid-capture (no preceding `;D`):
                        // append the pre-marker bytes to the current
                        // observation BEFORE deciding the next state.
                        // We deliberately KEEP the in-progress
                        // observation across the stray marker rather
                        // than starting fresh — concatenated output is
                        // more useful to the LLM than a silently
                        // dropped half. The reset below is gated on
                        // `!capturing` for exactly this reason.
                        if (capturing and offset > cursor) {
                            var end_at: u32 = offset;
                            if (offset <= output.len) {
                                var j: usize = offset;
                                while (j > cursor) : (j -= 1) {
                                    if (output[j - 1] == 0x1B) {
                                        end_at = @intCast(j - 1);
                                        break;
                                    }
                                }
                            }
                            if (end_at > cursor) {
                                appendCaptured(rt, output[cursor..@min(end_at, output.len)]);
                            }
                        }
                        if (!capturing and rt.dialog_state == .executing) {
                            rt.dialog_state = .capturing_output;
                            rt.captured_output_len = 0;
                            rt.captured_truncated = false;
                            capturing = true;
                        }
                        // Start capturing AFTER the marker's
                        // terminator byte.
                        cursor = @min(offset + 1, @as(u32, @intCast(output.len)));
                    },
                    .cmd_end, .prompt_start_implicit_end => {
                        if (capturing) {
                            // Slice ENDS at the ESC that begins
                            // the closing marker. Search backwards
                            // from `offset` for the most recent
                            // ESC byte within the current capture
                            // window.
                            var end_at: u32 = offset;
                            if (offset <= output.len) {
                                var j: usize = offset;
                                while (j > cursor) : (j -= 1) {
                                    if (output[j - 1] == 0x1B) {
                                        end_at = @intCast(j - 1);
                                        break;
                                    }
                                }
                            }
                            if (end_at > cursor) {
                                appendCaptured(rt, output[cursor..@min(end_at, output.len)]);
                            }
                            capturing = false;
                            rt.dialog_state = .observation_ready;
                            // Firing the next request from onOutput
                            // would mean doing JSON serialization +
                            // mutex acquisition on the master-output
                            // hot path. Defer to `onTick` instead —
                            // ~50ms latency is fine for a dialog
                            // loop where the LLM round-trip is the
                            // dominant cost anyway.
                        }
                        cursor = @min(offset + 1, @as(u32, @intCast(output.len)));
                    },
                }
            }
            if (capturing and cursor < output.len) {
                appendCaptured(rt, output[cursor..]);
            }
        }

        /// `.observation_ready` → `.generating` transition. Triggered
        /// here (not in onOutput) so the JSON serialization and
        /// mutex acquisition stay off the master-output hot path.
        pub fn onTick(rt: *Runtime, ctx: *m.Context, elapsed_ms: u64) m.Error!void {
            _ = elapsed_ms;
            if (rt.dialog_state != .observation_ready) return;

            // Push the observation as a turn, build the next
            // request, signal the worker. Any allocation failure
            // here aborts the dialog cleanly — we latch an error
            // and reset to idle so the user isn't stuck in a
            // half-state.
            const observation_slice = if (rt.captured_truncated)
                std.fmt.allocPrint(
                    rt.allocator,
                    "{s}\n[truncated — output exceeded {d} bytes]",
                    .{ rt.captured_output[0..rt.captured_output_len], cfg.captured_output_bytes },
                ) catch {
                    abortDialog(rt, ctx, "out of memory building observation");
                    return;
                }
            else
                rt.allocator.dupe(u8, rt.captured_output[0..rt.captured_output_len]) catch {
                    abortDialog(rt, ctx, "out of memory building observation");
                    return;
                };

            pushTurn(rt, .observation, observation_slice) catch {
                rt.allocator.free(observation_slice);
                abortDialog(rt, ctx, "out of memory recording observation");
                return;
            };
            rt.captured_output_len = 0;
            rt.captured_truncated = false;

            fireDialogRequest(rt, ctx) catch |err| {
                abortDialog(rt, ctx, switch (err) {
                    error.BodyTooLarge => "context too large — cancel and start a new task",
                    error.OutOfMemory => "out of memory firing follow-up request",
                    else => "internal error firing follow-up request",
                });
            };
        }

        /// Enter-key transition for dialog mode: while in
        /// `.suggesting`, the user just confirmed the suggested
        /// command — move to `.executing` so `onOutput` knows to
        /// start capturing when `;C` fires.
        ///
        /// Gated on a non-empty committed line: if the user
        /// deleted the suggestion before pressing Enter (or
        /// committed a blank line for any other reason), we'd
        /// otherwise eagerly capture the NEXT command's output as
        /// a stale observation. The reset is safer — the dialog
        /// returns to `.idle` (via dialogReset) and the user can
        /// retry from a clean state.
        pub fn onLineCommit(rt: *Runtime, ctx: *m.Context, line: []const u8) m.Error!void {
            if (rt.dialog_state != .suggesting) return;
            const trimmed = std.mem.trim(u8, line, " \t");
            if (trimmed.len == 0) {
                latchHint(rt, "empty command — dialog cancelled, retry from scratch");
                dialogReset(rt, ctx);
                rt.ai_mode_active = false;
                return;
            }
            rt.dialog_state = .executing;
        }

        pub fn pollShellInput(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            // Drain `pending_injection` ahead of the worker's
            // response. Used by the `onAction` path (Alt+A) to
            // route `\x15` (Ctrl+U) to the pty so the typed
            // `#: …` is wiped — onAction has no return-value
            // channel to the proxy. One-shot; cleared on read.
            if (rt.pending_injection_len > 0) {
                const n = rt.pending_injection_len;
                @memcpy(rt.inject_buf[0..n], rt.pending_injection[0..n]);
                rt.inject_len = n;
                rt.pending_injection_len = 0;
                return rt.inject_buf[0..n];
            }

            // Inner scope so the mutex is released BEFORE we run
            // the dialog-response handler, which may re-acquire
            // the mutex in `fireDialogRequest`.
            var res_kind: RequestKind = .single;
            var n: usize = 0;
            {
                rt.shared.mutex.lockUncancelable(ctx.io);
                defer rt.shared.mutex.unlock(ctx.io);
                if (!rt.shared.res_done) return null;
                // Drop responses from a stale generation — a newer
                // prompt has already been submitted; the worker's
                // reply for THAT one is still pending. Keep
                // `in_flight = true` because the user IS waiting on
                // the newer request; clearing it would prematurely
                // remove the 🧠 thinking… status.
                if (rt.shared.res_gen != rt.shared.req_gen) {
                    rt.shared.res_done = false;
                    rt.shared.res_len = 0;
                    rt.shared.explanation_len = 0;
                    rt.shared.error_len = 0;
                    return null;
                }
                res_kind = rt.shared.res_kind;
                n = rt.shared.res_len;
                @memcpy(rt.inject_buf[0..n], rt.shared.res_buf[0..n]);
                rt.inject_len = n;

                // Latch the explanation (single mode only). Dialog
                // responses never populate `explanation_buf` — the
                // worker leaves `explanation_len = 0` for dialog
                // kind because the JSON envelope's `description`
                // field is surfaced later (inside
                // `handleDialogResponse` via `latchHint`). The
                // shared `explanation_buf` is therefore dead weight
                // on the dialog path; kept around so single-mode
                // doesn't have to branch.
                const exp_n = rt.shared.explanation_len;
                if (n > 0 and exp_n > 0) {
                    @memcpy(rt.hint_buf[0..exp_n], rt.shared.explanation_buf[0..exp_n]);
                    rt.hint_len = exp_n;
                    rt.hint_pending = true;
                }

                // Failure path: nothing to inject, but the worker
                // may have latched a diagnostic. Surface it via the
                // *error* slot (not the hint slot) so it renders
                // in muted red with the ⚠ glyph.
                const err_n = rt.shared.error_len;
                if (n == 0 and err_n > 0) {
                    const copy_n = @min(err_n, rt.err_buf.len);
                    @memcpy(rt.err_buf[0..copy_n], rt.shared.error_buf[0..copy_n]);
                    rt.err_len = copy_n;
                    rt.err_pending = true;
                }

                rt.shared.res_done = false;
                rt.shared.res_len = 0;
                rt.shared.explanation_len = 0;
                rt.shared.error_len = 0;
            }
            rt.in_flight = false;

            // Dialog mode: parse the JSON envelope on the main
            // thread (where the runtime + state machine live) and
            // act on the LLM's instruction. Returns the bytes to
            // inject (the suggested command for `action=exec`) or
            // null for done/error/question paths.
            //
            // The `inject_buf` was populated with the raw JSON
            // envelope above by the shared-state copy — that's
            // the wrong thing to expose if any downstream caller
            // reads `rt.inject_buf[0..rt.inject_len]` directly
            // assuming it holds the next-injection bytes. Zero
            // `inject_len` now so any such stale read sees an
            // empty slice instead of JSON; the returned slice
            // from `handleDialogResponse` is the authoritative
            // injection payload for dialog mode.
            if (res_kind == .dialog) {
                rt.inject_len = 0;
                return try handleDialogResponse(rt, ctx, n);
            }

            // Single mode: n == 0 → worker signalled failure
            // (network error, non-2xx, parse failure). Nothing to
            // inject; the statusbar already cleared via
            // `in_flight = false`. The error hint above is what
            // the user will see.
            if (n == 0) return null;
            // Stage the line's author for the next submit() so
            // downstream consumers (atuin's --author tag,
            // guardrail's author-aware rules) see `.llm` instead
            // of the default `.user`. The flag persists in
            // line_state until submit() snapshots it; backspace /
            // killLine / killWord that empty the buffer reset it,
            // so a user who wipes and retypes still commits as
            // `.user`.
            ctx.line.setCommitAuthor(.llm);
            return rt.inject_buf[0..rt.inject_len];
        }

        /// Process a parsed dialog response. Branches by `action`:
        /// `exec` injects the command + transitions to `.suggesting`
        /// (description goes to the hint row); `done` clears state
        /// and latches a confirmation; `question` latches a
        /// "not yet wired" hint and resets (Question UI lands in a
        /// follow-up PR). Returns bytes to inject — for `exec`
        /// that's the command; for done/question/error it's null
        /// after queueing Ctrl+U on `pending_injection` so the
        /// suggested-command text gets wiped from the prompt.
        fn handleDialogResponse(rt: *Runtime, ctx: *m.Context, n: usize) m.Error!?[]const u8 {
            if (n == 0) {
                // Worker reported failure; the error slot already
                // has the diagnostic. End the dialog cleanly.
                dialogReset(rt, ctx);
                rt.ai_mode_active = false;
                queueInjection(rt, "\x15");
                return null;
            }

            const raw = rt.inject_buf[0..n];

            // Stash the raw response so it becomes the next
            // assistant_exec turn. Done before parsing so we have
            // it whether or not the JSON parses cleanly.
            const stash_n = @min(raw.len, rt.last_assistant_json.len);
            @memcpy(rt.last_assistant_json[0..stash_n], raw[0..stash_n]);
            rt.last_assistant_json_len = stash_n;

            var parsed: DialogResponse = .{};
            parseDialogResponse(rt.allocator, raw, &parsed) catch {
                latchErr(rt, "LLM reply wasn't valid JSON — cancel and retry");
                dialogReset(rt, ctx);
                rt.ai_mode_active = false;
                queueInjection(rt, "\x15");
                return null;
            };

            switch (parsed.action) {
                .exec => {
                    if (parsed.command_len == 0) {
                        latchErr(rt, "LLM reply had no command — cancel and retry");
                        dialogReset(rt, ctx);
                        rt.ai_mode_active = false;
                        queueInjection(rt, "\x15");
                        return null;
                    }
                    // Echo the assistant's JSON back to the model
                    // on the next turn so the conversation stays
                    // coherent.
                    const assistant_copy = rt.allocator.dupe(u8, rt.last_assistant_json[0..rt.last_assistant_json_len]) catch {
                        abortDialog(rt, ctx, "out of memory continuing dialog");
                        return null;
                    };
                    pushTurn(rt, .assistant_exec, assistant_copy) catch {
                        rt.allocator.free(assistant_copy);
                        abortDialog(rt, ctx, "out of memory continuing dialog");
                        return null;
                    };

                    // Stage the command for injection. Cap +
                    // copy in case the LLM's command exceeds
                    // `cfg.max_response_bytes` (shouldn't — the
                    // command field is bounded at parse time —
                    // but defensive).
                    const cmd = parsed.command();
                    const cmd_n = @min(cmd.len, rt.pending_command.len);
                    @memcpy(rt.pending_command[0..cmd_n], cmd[0..cmd_n]);
                    rt.pending_command_len = cmd_n;

                    if (parsed.description_len > 0) {
                        const desc = parsed.description();
                        const desc_n = @min(desc.len, rt.pending_description.len);
                        @memcpy(rt.pending_description[0..desc_n], desc[0..desc_n]);
                        rt.pending_description_len = desc_n;
                        latchHint(rt, desc);
                    }

                    rt.dialog_state = .suggesting;
                    // Same author-staging contract as single mode —
                    // see the matching call in `pollShellInput`.
                    ctx.line.setCommitAuthor(.llm);
                    // Return the command bytes for injection at
                    // the shell prompt — directly from
                    // `pending_command` so the buffer's role stays
                    // obvious (no second purpose-shifted reuse of
                    // `inject_buf`, which the single-mode path
                    // owns with different lifetime semantics).
                    return rt.pending_command[0..rt.pending_command_len];
                },
                .done => {
                    // Sized to fit the "✓ done — " prefix (~12
                    // bytes) plus the full 256-byte reason buffer
                    // without spilling into the fallback "✓ done".
                    var msg_buf: [320]u8 = undefined;
                    const reason = parsed.reason();
                    const msg = if (reason.len > 0)
                        std.fmt.bufPrint(&msg_buf, "✓ done — {s}", .{reason}) catch "✓ done"
                    else
                        "✓ done";
                    latchHint(rt, msg);
                    dialogReset(rt, ctx);
                    rt.ai_mode_active = false;
                    return null;
                },
                .question => {
                    latchHint(rt, "question UI lands in a follow-up PR — cancel and retry without ambiguity");
                    dialogReset(rt, ctx);
                    rt.ai_mode_active = false;
                    queueInjection(rt, "\x15");
                    return null;
                },
            }
        }

        /// Queue bytes on `pending_injection` for the next
        /// `pollShellInput` tick to drain. Single entry point for
        /// every site that wants to inject bytes synchronously
        /// from a hook that has no return-value channel (i.e.
        /// `onAction`). The compile-time assert pins the
        /// invariant — `pending_injection` is fixed at 16 bytes
        /// for the Ctrl+U / short-CSI use case; longer sequences
        /// need to grow the buffer first.
        fn queueInjection(rt: *Runtime, bytes: []const u8) void {
            std.debug.assert(bytes.len <= rt.pending_injection.len);
            @memcpy(rt.pending_injection[0..bytes.len], bytes);
            rt.pending_injection_len = bytes.len;
        }

        /// Synchronously latch a hint string on the Runtime so the
        /// next `provideHintText` tick surfaces it. For informational
        /// content (LLM explanation of the injected command).
        fn latchHint(rt: *Runtime, msg: []const u8) void {
            const n = @min(msg.len, rt.hint_buf.len);
            @memcpy(rt.hint_buf[0..n], msg[0..n]);
            rt.hint_len = n;
            rt.hint_pending = true;
        }

        /// Synchronously latch an error string on the Runtime so the
        /// next `provideErrorText` tick surfaces it (muted red + ⚠
        /// in the statusbar). Used by the onInput inert path (no
        /// worker involved) and by the test scaffolding.
        fn latchErr(rt: *Runtime, msg: []const u8) void {
            const n = @min(msg.len, rt.err_buf.len);
            @memcpy(rt.err_buf[0..n], msg[0..n]);
            rt.err_len = n;
            rt.err_pending = true;
        }

        // ---- dialog helpers ----------------------------------------------

        /// Append bytes to `captured_output`, respecting the cap.
        /// On overflow, set `captured_truncated = true` so the
        /// observation turn surfaces a `[truncated]` suffix. Caller
        /// doesn't need to know the bound — bytes silently drop
        /// when the buffer is full.
        fn appendCaptured(rt: *Runtime, bytes: []const u8) void {
            const room = rt.captured_output.len - rt.captured_output_len;
            if (bytes.len > room) {
                rt.captured_truncated = true;
                if (room == 0) return;
                @memcpy(rt.captured_output[rt.captured_output_len..][0..room], bytes[0..room]);
                rt.captured_output_len += room;
                return;
            }
            @memcpy(rt.captured_output[rt.captured_output_len..][0..bytes.len], bytes);
            rt.captured_output_len += bytes.len;
        }

        /// Push a turn onto the conversation history. `content`
        /// must be heap-allocated by the caller and is OWNED by the
        /// runtime after this call (freed in `freeTurns`). When
        /// already at `history_turns_max`, drops the OLDEST turn
        /// first (FIFO eviction). The truncation bound is the only
        /// memory pressure mitigation — without it, a long dialog
        /// would grow unbounded across the long-lived runtime.
        fn pushTurn(rt: *Runtime, kind: TurnKind, content: []u8) !void {
            // Truncate content to `cfg.max_turn_bytes` if oversized.
            // We re-allocate at the smaller size so `freeTurns`
            // doesn't free a partially-handed-over allocation.
            //
            // Ownership contract:
            //   - SUCCESS path: the runtime now owns `content` (or
            //     its truncated replacement). Caller MUST NOT free.
            //   - FAILURE path (any returned error): the CALLER
            //     still owns `content` and is responsible for the
            //     `free`. We achieve this by letting `try dupe`
            //     propagate the error BEFORE we'd `free(content)` —
            //     so a failed truncation leaves `content` untouched
            //     by us.
            const final_content: []u8 = if (content.len > cfg.max_turn_bytes) blk: {
                const trimmed = try rt.allocator.dupe(u8, content[0..cfg.max_turn_bytes]);
                rt.allocator.free(content);
                break :blk trimmed;
            } else content;

            if (rt.turns_len == cfg.history_turns_max) {
                // FIFO eviction — drop the oldest turn, shift the
                // rest down. O(n) per push but n ≤ 8, so totally
                // fine. Keeps the index/slot semantics simple.
                rt.allocator.free(rt.turns[0].content);
                for (1..rt.turns_len) |i| {
                    rt.turns[i - 1] = rt.turns[i];
                }
                rt.turns_len -= 1;
            }
            rt.turns[rt.turns_len] = .{ .kind = kind, .content = final_content };
            rt.turns_len += 1;
        }

        /// Free every turn's content + reset the count. Called on
        /// `detach` and on cancel so a follow-up dialog starts
        /// clean. Safe to call when `turns_len == 0`.
        fn freeTurns(rt: *Runtime) void {
            for (rt.turns[0..rt.turns_len]) |turn| {
                rt.allocator.free(turn.content);
            }
            rt.turns_len = 0;
        }

        /// Serialize the current conversation, hand it to the
        /// worker. Sets `dialog_state` to `.generating` on success.
        /// Returns `error.BodyTooLarge` when the serialized body
        /// exceeds `cfg.body_buf_bytes` (the conversation has
        /// outgrown the shared buffer — user needs to cancel).
        fn fireDialogRequest(rt: *Runtime, ctx: *m.Context) !void {
            const model_for_request: []const u8 = if (rt.current_model_idx < cfg.models.len)
                cfg.models[rt.current_model_idx]
            else
                cfg.model;

            // Build the JSON body OUTSIDE the mutex (allocator work,
            // potentially expensive). In fixture mode the worker
            // discards the body entirely, so skip the serialization
            // altogether.
            const built_body: ?[]u8 = if (cfg.fixture_responses.len > 0) null else blk: {
                const body = try buildDialogRequestBody(
                    rt.allocator,
                    model_for_request,
                    effective_dialog_system_prompt,
                    rt.shell,
                    rt.context_blob,
                    rt.turns[0..rt.turns_len],
                );
                if (body.len > cfg.body_buf_bytes) {
                    rt.allocator.free(body);
                    return error.BodyTooLarge;
                }
                break :blk body;
            };
            defer if (built_body) |b| rt.allocator.free(b);

            const idx_to_send: usize = if (cfg.models.len == 0)
                std.math.maxInt(usize)
            else if (rt.current_model_idx < cfg.models.len)
                rt.current_model_idx
            else
                0;

            // SINGLE critical section: body copy + metadata stamp
            // happen under one lock so the worker never sees a half-
            // written request (e.g. fresh body bytes with stale
            // `body_len`). Mirrors the single-mode trigger path's
            // copy-and-stamp-together shape.
            rt.shared.mutex.lockUncancelable(ctx.io);
            defer rt.shared.mutex.unlock(ctx.io);
            if (built_body) |b| {
                @memcpy(rt.shared.body_buf[0..b.len], b);
                rt.shared.body_len = b.len;
            } else {
                rt.shared.body_len = 0;
            }
            rt.shared.model_idx = idx_to_send;
            rt.shared.req_kind = .dialog;
            rt.shared.req_pending = true;
            rt.shared.req_gen +%= 1;
            rt.shared.res_done = false;
            rt.shared.res_len = 0;
            rt.shared.cv.signal(ctx.io);
            rt.in_flight = true;
            rt.dialog_state = .generating;
        }

        /// Reset all dialog state — used by both `abortDialog` and
        /// the `llm_exec_cancel` action. Bumps `req_gen` so any
        /// in-flight worker response is discarded as stale; clears
        /// `req_pending` so a queued-but-not-yet-picked-up request
        /// doesn't fire AFTER the cancel (which would otherwise
        /// burn a wasted API call AND advance `shared.fixture_idx`,
        /// desynchronising the fixture cursor across cancel-aware
        /// e2e scenarios).
        fn dialogReset(rt: *Runtime, ctx: *m.Context) void {
            rt.shared.mutex.lockUncancelable(ctx.io);
            rt.shared.req_gen +%= 1;
            rt.shared.req_pending = false;
            rt.shared.res_done = false;
            rt.shared.res_len = 0;
            rt.shared.mutex.unlock(ctx.io);

            freeTurns(rt);
            rt.dialog_state = .idle;
            rt.captured_output_len = 0;
            rt.captured_truncated = false;
            rt.pending_command_len = 0;
            rt.pending_description_len = 0;
            rt.last_assistant_json_len = 0;
            rt.in_flight = false;
        }

        /// Abort the dialog with an error notification. Surfaces in
        /// the ⚠ row and resets to idle. Used for unrecoverable
        /// states mid-loop (OOM, body too large, malformed JSON
        /// from the model on second attempt).
        fn abortDialog(rt: *Runtime, ctx: *m.Context, msg: []const u8) void {
            latchErr(rt, msg);
            dialogReset(rt, ctx);
            rt.ai_mode_active = false;
            queueInjection(rt, "\x15");
        }

        /// One-shot hint surface: returns the latched explanation
        /// the first time it's called after a fresh response, then
        /// returns null until the next response arrives. Cleared
        /// on read so the hint row's TTL governs how long the
        /// text stays visible — the module doesn't keep
        /// re-painting.
        pub fn provideHintText(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            _ = ctx;
            if (!rt.hint_pending) return null;
            rt.hint_pending = false;
            return rt.hint_buf[0..rt.hint_len];
        }

        /// Sibling of `provideHintText` — surfaces a latched error
        /// notification (muted-red row above the status bar). Same
        /// one-shot semantics as `provideHintText`.
        pub fn provideErrorText(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            _ = ctx;
            if (!rt.err_pending) return null;
            rt.err_pending = false;
            return rt.err_buf[0..rt.err_len];
        }

        pub fn statusText(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            if (rt.in_flight) return "\u{1F9E0} thinking…";

            // AI mode hint: when the line starts with the prefix,
            // surface the action keys so users discover the new
            // workflow. Takes precedence over the older single-
            // glyph `prefix_signal_status_text` indicator so the
            // hint string is what shows once the user has typed
            // `#: `.
            //
            // `Esc cancel` is intentionally NOT advertised here —
            // no Esc handler is wired yet on the proxy side and
            // advertising a key that doesn't fire would mislead
            // users. `Ctrl+Shift+X` (`llm_exec_cancel`) is the
            // actual cancel binding; it's discoverable via Alt+H
            // once the help overlay lands.
            if (rt.ai_mode_active) {
                // With a configured `models[]` list, surface the
                // current pick inline so `Alt+M` cycling has
                // immediate visible feedback in the statusbar
                // (not just a transient latched hint). When the
                // user has only the legacy `cfg.model` (no list),
                // the static hint is fine — no point baking the
                // single name into the bar.
                if (cfg.models.len > 0) {
                    const pick = cfg.models[rt.current_model_idx];
                    return std.fmt.bufPrint(
                        &rt.status_buf,
                        "\u{2728} AI · Alt+A single · Alt+S dialog · Alt+Shift+S auto · Alt+M {s} · Alt+H help · Ctrl+Shift+X cancel",
                        .{pick},
                    ) catch "\u{2728} AI · Alt+A single · Alt+S dialog · Alt+Shift+S auto · Alt+M model · Alt+H help · Ctrl+Shift+X cancel";
                }
                return "\u{2728} AI · Alt+A single · Alt+S dialog · Alt+Shift+S auto · Alt+M model · Alt+H help · Ctrl+Shift+X cancel";
            }

            // Legacy prefix signal — kept for users who set the
            // older `prefix_signal_status_text` to something custom
            // and don't want the verbose AI hint. Reachable only
            // when `ai_mode_active` is false (above branch took
            // precedence), which today is the same condition as
            // "prefix not matched" since the flag is wired to the
            // same check. Keeping the code path so a future change
            // (e.g. a config knob to suppress the verbose hint)
            // doesn't break custom users.
            if (cfg.prefix_signal_status) {
                const line = ctx.line.current();
                if (std.mem.startsWith(u8, line, cfg.prefix)) {
                    return cfg.prefix_signal_status_text;
                }
            }
            return null;
        }

        // Pre-built OSC escape strings; comptime-baked from the
        // configured colour so we don't allocate per tick.
        const cursor_set_seq = "\x1B]12;" ++ cfg.prefix_signal_cursor_color ++ "\x07";
        const cursor_reset_seq = "\x1B]112\x07";

        /// Bytes to write to the user's outer terminal (NOT the
        /// pty.master, which goes to the shell). Used here for OSC
        /// 12 / 112 cursor-colour transitions while the user is
        /// typing a prefix-matched prompt. One-shot per transition
        /// — we only emit on edges so the terminal doesn't see
        /// redundant OSC traffic on every tick.
        pub fn provideTermBytes(rt: *Runtime, ctx: *m.Context) m.Error!?[]const u8 {
            if (!cfg.prefix_signal_cursor) return null;
            const line = ctx.line.current();
            const matches = std.mem.startsWith(u8, line, cfg.prefix);
            if (matches and !rt.cursor_signal_active) {
                rt.cursor_signal_active = true;
                return cursor_set_seq;
            }
            if (!matches and rt.cursor_signal_active) {
                rt.cursor_signal_active = false;
                return cursor_reset_seq;
            }
            return null;
        }

        // ---- worker -------------------------------------------------------

        fn worker(
            shared: *Shared,
            io: std.Io,
            gpa: std.mem.Allocator,
            api_base: []const u8,
            api_key: []const u8,
            shell_name: []const u8,
            context_blob: []const u8,
        ) void {
            var prompt_local: [cfg.max_prompt_bytes]u8 = undefined;
            var body_local: [cfg.body_buf_bytes]u8 = undefined;
            var prompt_len: usize = 0;
            var body_len: usize = 0;
            var serving_gen: u64 = 0;
            while (true) {
                shared.mutex.lockUncancelable(io);
                while (!shared.shutdown and !shared.req_pending) {
                    shared.cv.waitUncancelable(io, &shared.mutex);
                }
                if (shared.shutdown) {
                    shared.mutex.unlock(io);
                    return;
                }
                const req_kind = shared.req_kind;
                serving_gen = shared.req_gen;
                shared.req_pending = false;

                // Fixture mode — bypass HTTP entirely. Pop the next
                // canned response from the shared cursor (wrapping
                // modulo list length). Branch FIRST so we skip the
                // req_buf / body_buf copy below: fixture responses
                // don't depend on the request body at all, copying
                // it would be dead work.
                //
                // **Stamping contract**: even in fixture mode we
                // stamp `res_kind` and `res_gen` exactly like the
                // HTTP path so `pollShellInput`'s stale-response
                // guard and dialog/single discriminator work
                // identically. The `shared.model_idx` read is the
                // ONLY field intentionally skipped here (fixture
                // responses are model-agnostic).
                if (cfg.fixture_responses.len > 0) {
                    const fixture_n = cfg.fixture_responses.len;
                    const fi = shared.fixture_idx % fixture_n;
                    shared.fixture_idx = (fi + 1) % fixture_n;
                    const canned = cfg.fixture_responses[fi];
                    const copy_n = @min(canned.len, shared.res_buf.len);
                    @memcpy(shared.res_buf[0..copy_n], canned[0..copy_n]);
                    shared.res_len = copy_n;
                    shared.explanation_len = 0;
                    shared.error_len = 0;
                    shared.res_gen = serving_gen;
                    shared.res_kind = req_kind;
                    shared.res_done = true;
                    shared.mutex.unlock(io);
                    continue;
                }

                if (req_kind == .single) {
                    prompt_len = shared.req_len;
                    @memcpy(prompt_local[0..prompt_len], shared.req_buf[0..prompt_len]);
                } else {
                    body_len = shared.body_len;
                    @memcpy(body_local[0..body_len], shared.body_buf[0..body_len]);
                }
                // Read the request-time model INDEX under the same
                // lock. Trigger sites set `model_idx` to either a
                // valid `cfg.models[]` index, or `usize.max` as the
                // "no list, use cfg.model" sentinel. We resolve the
                // slice AFTER releasing the lock — `cfg.models` is
                // comptime-static, the resolved slice's storage
                // outlives the worker thread.
                const idx = shared.model_idx;
                shared.mutex.unlock(io);

                const model_for_request: []const u8 = if (idx < cfg.models.len)
                    cfg.models[idx]
                else
                    cfg.model;

                // Fire the HTTP request OUTSIDE the lock — it may
                // block for many seconds.
                var response_buf: [cfg.max_response_bytes]u8 = undefined;
                var explanation_local: [512]u8 = undefined;
                var error_local: [256]u8 = undefined;
                const result = if (req_kind == .single)
                    doRequest(
                        gpa,
                        io,
                        api_base,
                        api_key,
                        shell_name,
                        context_blob,
                        prompt_local[0..prompt_len],
                        model_for_request,
                        &response_buf,
                        &explanation_local,
                        &error_local,
                    ) catch RequestResult{
                        .cmd_len = 0,
                        .exp_len = 0,
                        .err_len = writeStatic(&error_local, "internal error in worker"),
                    }
                else
                    doDialogRequest(
                        gpa,
                        io,
                        api_base,
                        api_key,
                        body_local[0..body_len],
                        &response_buf,
                        &error_local,
                    ) catch RequestResult{
                        .cmd_len = 0,
                        .exp_len = 0,
                        .err_len = writeStatic(&error_local, "internal error in worker"),
                    };

                // Signal completion regardless of outcome — proxy
                // needs to clear `in_flight` so the 🧠 thinking…
                // statusbar doesn't stick when a request fails.
                // The proxy filters stale-generation responses
                // separately.
                shared.mutex.lockUncancelable(io);
                if (result.cmd_len > 0) {
                    @memcpy(shared.res_buf[0..result.cmd_len], response_buf[0..result.cmd_len]);
                    shared.res_len = result.cmd_len;
                    if (result.exp_len > 0) {
                        @memcpy(shared.explanation_buf[0..result.exp_len], explanation_local[0..result.exp_len]);
                        shared.explanation_len = result.exp_len;
                    } else {
                        shared.explanation_len = 0;
                    }
                    shared.error_len = 0;
                } else {
                    shared.res_len = 0;
                    shared.explanation_len = 0;
                    if (result.err_len > 0) {
                        const en = @min(result.err_len, shared.error_buf.len);
                        @memcpy(shared.error_buf[0..en], error_local[0..en]);
                        shared.error_len = en;
                    } else {
                        shared.error_len = 0;
                    }
                }
                shared.res_gen = serving_gen;
                shared.res_kind = req_kind;
                shared.res_done = true;
                shared.mutex.unlock(io);
            }
        }

        const RequestResult = struct { cmd_len: usize, exp_len: usize, err_len: usize = 0 };

        /// Write a static string into `dst` and return how many
        /// bytes were written (truncated to fit). Used to populate
        /// error messages with stable literals.
        fn writeStatic(dst: []u8, src: []const u8) usize {
            const n = @min(src.len, dst.len);
            @memcpy(dst[0..n], src[0..n]);
            return n;
        }

        /// One HTTP round-trip. On success returns `cmd_len > 0`
        /// and (when the model emitted one) `exp_len > 0`. On any
        /// failure `cmd_len == 0` and `err_len > 0` with a
        /// human-readable explanation written into `error_out`
        /// (network error, HTTP non-2xx with status code,
        /// unparseable response, sanitiser stripped everything).
        fn doRequest(
            gpa: std.mem.Allocator,
            io: std.Io,
            api_base: []const u8,
            api_key: []const u8,
            shell_name: []const u8,
            context_blob: []const u8,
            prompt: []const u8,
            model: []const u8,
            out: []u8,
            explanation_out: []u8,
            error_out: []u8,
        ) !RequestResult {
            const url = try std.fmt.allocPrint(gpa, "{s}/chat/completions", .{api_base});
            defer gpa.free(url);

            const body = try buildRequestBody(gpa, model, effective_system_prompt, shell_name, context_blob, prompt);
            defer gpa.free(body);

            var auth_buf: [256]u8 = undefined;
            const auth_header: ?[]const u8 = blk: {
                if (api_key.len == 0) break :blk null;
                if (api_key.len + 7 > auth_buf.len) break :blk null;
                break :blk std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{api_key}) catch null;
            };

            var headers_buf: [2]std.http.Header = undefined;
            var headers_len: usize = 0;
            headers_buf[headers_len] = .{ .name = "Content-Type", .value = "application/json" };
            headers_len += 1;
            if (auth_header) |h| {
                headers_buf[headers_len] = .{ .name = "Authorization", .value = h };
                headers_len += 1;
            }

            var client: std.http.Client = .{ .allocator = gpa, .io = io };
            defer client.deinit();

            // Cap the response body at `max_response_bytes * 16`.
            // The JSON envelope around the message content is
            // larger than the content itself; 16× is a comfortable
            // ceiling for typical chat-completion shapes. A
            // misbehaving endpoint streaming gigabytes can no
            // longer OOM the worker — `client.fetch` errors when
            // the fixed writer overflows; we catch it and return 0
            // (no partial parse — a truncated JSON envelope is
            // useless anyway).
            const response_cap = cfg.max_response_bytes * 16;
            var response_buf: [response_cap]u8 = undefined;
            var response_writer: std.Io.Writer = .fixed(&response_buf);

            const fetched = client.fetch(.{
                .location = .{ .url = url },
                .method = .POST,
                .payload = body,
                .extra_headers = headers_buf[0..headers_len],
                .response_writer = &response_writer,
            }) catch return RequestResult{
                .cmd_len = 0,
                .exp_len = 0,
                .err_len = writeStatic(error_out, "request failed (endpoint unreachable?)"),
            };

            const status = @intFromEnum(fetched.status);
            if (status < 200 or status >= 300) {
                const err_msg = std.fmt.bufPrint(error_out, "HTTP {d}", .{status}) catch
                    error_out[0..writeStatic(error_out, "HTTP error")];
                return RequestResult{ .cmd_len = 0, .exp_len = 0, .err_len = err_msg.len };
            }

            const extracted = extractResponse(response_buf[0..response_writer.end], out, explanation_out);
            if (extracted.cmd_len == 0) {
                return RequestResult{
                    .cmd_len = 0,
                    .exp_len = 0,
                    .err_len = writeStatic(error_out, "couldn't extract a command from the response"),
                };
            }
            return RequestResult{ .cmd_len = extracted.cmd_len, .exp_len = extracted.explanation_len };
        }

        /// Dialog-mode HTTP round-trip. The request body is already
        /// built (by `buildDialogRequestBody` on the main thread)
        /// because it depends on conversation history that lives in
        /// `Runtime`; the worker just POSTs it and extracts the
        /// raw assistant `content` field. Differs from `doRequest`
        /// in that the result `out` slice holds the *JSON envelope*
        /// (`{"action":...,"command":...}`) — `pollShellInput` does
        /// the second-stage parse on the main thread where the
        /// runtime + allocator + state machine live.
        fn doDialogRequest(
            gpa: std.mem.Allocator,
            io: std.Io,
            api_base: []const u8,
            api_key: []const u8,
            body: []const u8,
            out: []u8,
            error_out: []u8,
        ) !RequestResult {
            const url = try std.fmt.allocPrint(gpa, "{s}/chat/completions", .{api_base});
            defer gpa.free(url);

            var auth_buf: [256]u8 = undefined;
            const auth_header: ?[]const u8 = blk: {
                if (api_key.len == 0) break :blk null;
                if (api_key.len + 7 > auth_buf.len) break :blk null;
                break :blk std.fmt.bufPrint(&auth_buf, "Bearer {s}", .{api_key}) catch null;
            };

            var headers_buf: [2]std.http.Header = undefined;
            var headers_len: usize = 0;
            headers_buf[headers_len] = .{ .name = "Content-Type", .value = "application/json" };
            headers_len += 1;
            if (auth_header) |h| {
                headers_buf[headers_len] = .{ .name = "Authorization", .value = h };
                headers_len += 1;
            }

            var client: std.http.Client = .{ .allocator = gpa, .io = io };
            defer client.deinit();

            // Heap-allocate the response buffer — at the default
            // cfg.max_response_bytes=4KiB this is 64 KiB which is
            // a substantial stack frame inside the worker thread.
            // Scales with the comptime knob, so a user raising
            // max_response_bytes shouldn't silently push the worker
            // thread close to its stack limit.
            const response_cap = cfg.max_response_bytes * 16;
            const response_buf = gpa.alloc(u8, response_cap) catch return RequestResult{
                .cmd_len = 0,
                .exp_len = 0,
                .err_len = writeStatic(error_out, "out of memory allocating response buffer"),
            };
            defer gpa.free(response_buf);
            var response_writer: std.Io.Writer = .fixed(response_buf);

            const fetched = client.fetch(.{
                .location = .{ .url = url },
                .method = .POST,
                .payload = body,
                .extra_headers = headers_buf[0..headers_len],
                .response_writer = &response_writer,
            }) catch return RequestResult{
                .cmd_len = 0,
                .exp_len = 0,
                .err_len = writeStatic(error_out, "request failed (endpoint unreachable?)"),
            };

            const status = @intFromEnum(fetched.status);
            if (status < 200 or status >= 300) {
                const err_msg = std.fmt.bufPrint(error_out, "HTTP {d}", .{status}) catch
                    error_out[0..writeStatic(error_out, "HTTP error")];
                return RequestResult{ .cmd_len = 0, .exp_len = 0, .err_len = err_msg.len };
            }

            const n = extractRawContent(response_buf[0..response_writer.end], out);
            if (n == 0) {
                return RequestResult{
                    .cmd_len = 0,
                    .exp_len = 0,
                    .err_len = writeStatic(error_out, "empty response from model"),
                };
            }
            return RequestResult{ .cmd_len = n, .exp_len = 0 };
        }

        // ---- pure helpers (testable) -------------------------------------

        /// Build the JSON request body. Pure — no I/O. Exposed for
        /// testing so we can assert exact shape without a server.
        pub fn buildRequestBody(
            allocator: std.mem.Allocator,
            model: []const u8,
            system_prompt: []const u8,
            shell_name: []const u8,
            context_blob: []const u8,
            prompt: []const u8,
        ) ![]u8 {
            var allocating: std.Io.Writer.Allocating = .init(allocator);
            errdefer allocating.deinit();
            const writer = &allocating.writer;

            try writer.writeAll("{\"model\":");
            try std.json.Stringify.encodeJsonString(model, .{}, writer);
            try writer.writeAll(",\"messages\":[{\"role\":\"system\",\"content\":");
            try std.json.Stringify.encodeJsonString(system_prompt, .{}, writer);
            try writer.writeAll("},{\"role\":\"user\",\"content\":");

            // allocPrint instead of a fixed buffer — `shell_name`
            // and `context_blob` come from $SHELL / env config and
            // are not length-bounded. A pathological override (or
            // an unusually long env value) would overflow a fixed
            // buffer. Heap is fine — this is a one-shot build per
            // request, off the hot path.
            const user_msg = if (context_blob.len > 0)
                try std.fmt.allocPrint(
                    allocator,
                    "Generate a {s} command to: {s}\n\nContext: {s}",
                    .{ shell_name, prompt, context_blob },
                )
            else
                try std.fmt.allocPrint(
                    allocator,
                    "Generate a {s} command to: {s}",
                    .{ shell_name, prompt },
                );
            defer allocator.free(user_msg);
            try std.json.Stringify.encodeJsonString(user_msg, .{}, writer);
            try writer.writeAll("}],\"stream\":false}");
            return allocating.toOwnedSlice();
        }

        /// Build the dialog-mode JSON request body. Pure — no I/O.
        /// Serializes the system prompt + the full conversation
        /// history as a sequence of OpenAI-style messages. Observation
        /// turns are wrapped as user messages prefixed with
        /// `OBSERVATION:` so the model recognizes them as command
        /// output rather than a fresh task. Caller frees the slice.
        pub fn buildDialogRequestBody(
            allocator: std.mem.Allocator,
            model: []const u8,
            system_prompt: []const u8,
            shell_name: []const u8,
            context_blob: []const u8,
            turns: []const Turn,
        ) ![]u8 {
            var allocating: std.Io.Writer.Allocating = .init(allocator);
            errdefer allocating.deinit();
            const writer = &allocating.writer;

            // Compose the system message: configured system prompt
            // PLUS a stable shell/context preamble. Putting shell
            // name + context_blob on the SYSTEM message (rather than
            // wrapping the first user turn) means they survive FIFO
            // eviction — once history fills past `history_turns_max`
            // and the original user task ages out, future requests
            // would otherwise lose every trace of shell context.
            // The system message is always rebuilt per request, so
            // there's no historical-rewrite concern either.
            const composed_system = if (context_blob.len > 0)
                try std.fmt.allocPrint(
                    allocator,
                    "{s}\n\nShell: {s}\nContext: {s}",
                    .{ system_prompt, shell_name, context_blob },
                )
            else
                try std.fmt.allocPrint(
                    allocator,
                    "{s}\n\nShell: {s}",
                    .{ system_prompt, shell_name },
                );
            defer allocator.free(composed_system);

            try writer.writeAll("{\"model\":");
            try std.json.Stringify.encodeJsonString(model, .{}, writer);
            try writer.writeAll(",\"messages\":[{\"role\":\"system\",\"content\":");
            try std.json.Stringify.encodeJsonString(composed_system, .{}, writer);
            try writer.writeAll("}");

            for (turns) |turn| {
                const role: []const u8 = switch (turn.kind) {
                    .assistant_exec => "assistant",
                    .user, .observation => "user",
                };
                try writer.writeAll(",{\"role\":\"");
                try writer.writeAll(role);
                try writer.writeAll("\",\"content\":");

                if (turn.kind == .observation) {
                    const wrapped = try std.fmt.allocPrint(
                        allocator,
                        "OBSERVATION:\n{s}",
                        .{turn.content},
                    );
                    defer allocator.free(wrapped);
                    try std.json.Stringify.encodeJsonString(wrapped, .{}, writer);
                } else {
                    try std.json.Stringify.encodeJsonString(turn.content, .{}, writer);
                }
                try writer.writeAll("}");
            }

            try writer.writeAll("],\"stream\":false}");
            return allocating.toOwnedSlice();
        }

        /// Parse a dialog response (the raw assistant content
        /// returned by `extractRawContent`). `std.json.parseFromSlice`
        /// owns an internal arena which is released by
        /// `parsed.deinit()` — we copy out the fields we care about
        /// into fixed-size buffers on the returned struct BEFORE
        /// `deinit` fires, so the slices we hand back point at the
        /// caller's `out` storage, not at arena-owned memory.
        /// `ignore_unknown_fields` is on so a model emitting extra
        /// keys doesn't error out the loop.
        pub fn parseDialogResponse(
            allocator: std.mem.Allocator,
            raw: []const u8,
            out: *DialogResponse,
        ) !void {
            // `std.json.parseFromSlice` returns a `Parsed(T)` whose
            // `.deinit()` frees an INTERNAL arena allocated through
            // the passed allocator. Wrapping our own arena AROUND
            // that and calling both `arena.deinit()` and
            // `parsed.deinit()` would be redundant at best and
            // dangerous at worst (double free of arena-owned
            // storage on some Zig versions). Use `parsed.deinit()`
            // alone — it owns everything `parsed.value` references.
            const Parsed = struct {
                action: []const u8,
                command: ?[]const u8 = null,
                description: ?[]const u8 = null,
                reason: ?[]const u8 = null,
                question: ?[]const u8 = null,
            };

            const parsed = std.json.parseFromSlice(
                Parsed,
                allocator,
                raw,
                .{ .ignore_unknown_fields = true, .allocate = .alloc_always },
            ) catch return error.MalformedJson;
            defer parsed.deinit();

            const action_enum = std.meta.stringToEnum(DialogAction, parsed.value.action) orelse return error.UnknownAction;
            out.* = .{ .action = action_enum };

            if (parsed.value.command) |c| {
                const n = @min(c.len, out.command_buf.len);
                @memcpy(out.command_buf[0..n], c[0..n]);
                out.command_len = n;
            }
            if (parsed.value.description) |d| {
                const n = @min(d.len, out.description_buf.len);
                @memcpy(out.description_buf[0..n], d[0..n]);
                out.description_len = n;
            }
            if (parsed.value.reason) |r| {
                const n = @min(r.len, out.reason_buf.len);
                @memcpy(out.reason_buf[0..n], r[0..n]);
                out.reason_len = n;
            }
            // `question` is parsed but not surfaced in this PR —
            // questions land in the Question UI follow-up. Caller
            // checks `action == .question` and emits a "not yet
            // wired" hint without inspecting the question text.
        }

        /// Result of `extractResponse` — both halves of the model's
        /// reply when configured to emit an explanation + command.
        pub const ExtractedResponse = struct {
            cmd_len: usize,
            explanation_len: usize,
        };

        /// Extract the assistant's command text from an OpenAI-style
        /// chat-completion JSON response. Strips surrounding markdown
        /// fences + leading/trailing whitespace, takes the first
        /// non-empty line. Returns bytes written to `out`, or 0 on
        /// parse failure / empty result.
        pub fn extractCommand(body: []const u8, out: []u8) usize {
            var decoded_buf: [cfg.max_response_bytes]u8 = undefined;
            const decoded_len = decodeContent(body, &decoded_buf);
            if (decoded_len == 0) return 0;
            return sanitizeCommand(decoded_buf[0..decoded_len], out);
        }

        /// Extract both the explanation (prose before the fence) and
        /// the command (inside the fence) from a model reply that
        /// uses the with-explanation format:
        ///
        ///     <one-line explanation>
        ///     ```
        ///     <command>
        ///     ```
        ///
        /// When the model didn't follow the format (no fence), the
        /// whole content is treated as the command and explanation
        /// is empty. When the JSON content field is missing, both
        /// lengths come back 0.
        pub fn extractResponse(body: []const u8, cmd_out: []u8, explanation_out: []u8) ExtractedResponse {
            var decoded_buf: [cfg.max_response_bytes]u8 = undefined;
            const decoded_len = decodeContent(body, &decoded_buf);
            if (decoded_len == 0) return .{ .cmd_len = 0, .explanation_len = 0 };
            const decoded = decoded_buf[0..decoded_len];

            // Look for an opening fence. The model may or may not
            // prefix prose; if there's no fence we keep the old
            // single-string behaviour.
            const fence_open_idx = std.mem.indexOf(u8, decoded, "```") orelse {
                return .{
                    .cmd_len = sanitizeCommand(decoded, cmd_out),
                    .explanation_len = 0,
                };
            };

            // Inner content of the fence — skip the optional
            // language tag (everything up to the first newline
            // after the opening backticks). Bail to legacy mode
            // if the fence isn't terminated.
            const after_open = fence_open_idx + 3;
            const inner_start = if (std.mem.indexOfScalar(u8, decoded[after_open..], '\n')) |nl|
                after_open + nl + 1
            else
                after_open;
            const fence_close_idx = std.mem.indexOfPos(u8, decoded, inner_start, "```") orelse {
                return .{
                    .cmd_len = sanitizeCommand(decoded, cmd_out),
                    .explanation_len = 0,
                };
            };

            const explanation_raw = std.mem.trim(u8, decoded[0..fence_open_idx], " \t\r\n");
            const fence_body = decoded[inner_start..fence_close_idx];
            return .{
                .cmd_len = sanitizeCommand(fence_body, cmd_out),
                .explanation_len = sanitizeExplanation(explanation_raw, explanation_out),
            };
        }

        /// Dialog-mode response extraction. Returns the raw content
        /// field VERBATIM (after JSON-unescape) so the main thread
        /// can parse the inner JSON envelope. Strips markdown
        /// ```json fences if the model wrapped its reply despite
        /// the system prompt forbidding it — common with smaller
        /// models that "helpfully" format JSON.
        pub fn extractRawContent(body: []const u8, out: []u8) usize {
            const decoded_len = decodeContent(body, out);
            if (decoded_len == 0) return 0;
            const decoded = out[0..decoded_len];
            const trimmed = std.mem.trim(u8, decoded, " \t\r\n");

            // Strip an outer ```json …``` fence if present. We DO
            // this even though the system prompt says "no fences"
            // because the alternative is a fragile dialog loop —
            // a single fence-wrapped reply would tank the whole
            // session for users running locally-quantized models.
            //
            // Fence parsing is best-effort: if the boundaries
            // can't be located cleanly (no newline after the
            // opening fence, no closing fence, close before open),
            // we FALL THROUGH to returning the trimmed input
            // untouched. Better the JSON parser sees the wrapped
            // text and complains specifically than silently
            // dropping an otherwise-parseable reply.
            //
            // Closing fence is located by FORWARD search from
            // after_open (`indexOfPos`), not by `lastIndexOf`.
            // The latter would match the trailing fence even when
            // a nested triple-backtick appears earlier in the
            // content (e.g. a description string containing literal
            // fences) — but if an interior fence preceded the real
            // closer, lastIndexOf would silently truncate. Forward
            // search picks the FIRST closing fence after the
            // opener, which is the conventional shape.
            fence_strip: {
                if (!std.mem.startsWith(u8, trimmed, "```")) break :fence_strip;
                const nl = std.mem.indexOfScalar(u8, trimmed[3..], '\n') orelse break :fence_strip;
                const after_open = 3 + nl + 1;
                const close_at = std.mem.indexOfPos(u8, trimmed, after_open, "```") orelse break :fence_strip;
                if (close_at <= after_open) break :fence_strip;
                const inner = std.mem.trim(u8, trimmed[after_open..close_at], " \t\r\n");
                @memmove(out[0..inner.len], inner);
                return inner.len;
            }

            if (trimmed.ptr != decoded.ptr) {
                @memmove(out[0..trimmed.len], trimmed);
            }
            return trimmed.len;
        }

        // Pure response/sanitization helpers extracted to
        // `llm/parse.zig` — see there for security rationale and
        // tests.
        pub const decodeContent = parse.decodeContent;
        pub const sanitizeExplanation = parse.sanitizeExplanation;
        pub const stripControlBytes = parse.stripControlBytes;
        pub const sanitizeCommand = parse.sanitizeCommand;
    };
}

// ===========================================================================
// Tests
// ===========================================================================

const testing = std.testing;
const test_io: std.Io = std.Io.failing;

// Pull in sibling parse-tests so `unit_tests.zig`'s single
// `_ = @import("modules/llm.zig")` line discovers them.
test {
    _ = parse;
}

test "configure exposes the expected hooks" {
    const L = configure(.{});
    try testing.expect(@hasDecl(L, "onInput"));
    try testing.expect(@hasDecl(L, "pollShellInput"));
    try testing.expect(@hasDecl(L, "statusText"));
    try testing.expectEqualStrings("llm", L.name);
}

test "buildRequestBody produces well-formed OpenAI chat-completion JSON" {
    const L = configure(.{ .model = "test-model" });
    const body = try L.buildRequestBody(testing.allocator, "test-model", "be terse", "bash", "", "list zig files");
    defer testing.allocator.free(body);

    try testing.expect(std.mem.indexOf(u8, body, "\"model\":\"test-model\"") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\"role\":\"system\"") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\"role\":\"user\"") != null);
    try testing.expect(std.mem.indexOf(u8, body, "be terse") != null);
    try testing.expect(std.mem.indexOf(u8, body, "Generate a bash command to: list zig files") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\"stream\":false") != null);
    // No raw newlines in the JSON — system prompt may have them
    // and they must be escaped to \n.
    for (body) |c| try testing.expect(c != '\n');
}

test "buildRequestBody escapes user content correctly (quotes + backslashes)" {
    const L = configure(.{});
    const body = try L.buildRequestBody(
        testing.allocator,
        "m",
        "sys",
        "bash",
        "",
        "echo \"hello\\world\"",
    );
    defer testing.allocator.free(body);
    try testing.expect(std.mem.indexOf(u8, body, "\\\"hello") != null);
    try testing.expect(std.mem.indexOf(u8, body, "\\\\world") != null);
}

test "buildRequestBody appends a context blob when provided" {
    const L = configure(.{});
    const body = try L.buildRequestBody(
        testing.allocator,
        "m",
        "sys",
        "bash",
        "PATH_BASE=/opt/foo, PROJECT=acme",
        "list files",
    );
    defer testing.allocator.free(body);
    // The user message should now include "Context: …" after the
    // task; the literal commas + paths must survive JSON encoding
    // (commas are not escaped — `/` may be encoded as `\/` but
    // we expect it bare since we don't request slash escapes).
    try testing.expect(std.mem.indexOf(u8, body, "Generate a bash command to: list files") != null);
    try testing.expect(std.mem.indexOf(u8, body, "Context: PATH_BASE=/opt/foo, PROJECT=acme") != null);
}

test "buildRequestBody omits the context section entirely when blob is empty" {
    const L = configure(.{});
    const body = try L.buildRequestBody(
        testing.allocator,
        "m",
        "sys",
        "bash",
        "",
        "list files",
    );
    defer testing.allocator.free(body);
    try testing.expect(std.mem.indexOf(u8, body, "Context:") == null);
}

test "extractCommand pulls choices[0].message.content out of a chat response" {
    const L = configure(.{});
    var out: [64]u8 = undefined;
    const sample =
        \\{"id":"x","choices":[{"index":0,"message":{"role":"assistant","content":"ls *.zig"}}]}
    ;
    const n = L.extractCommand(sample, &out);
    try testing.expectEqualStrings("ls *.zig", out[0..n]);
}

test "extractCommand strips ```bash code fences" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    const sample =
        "{\"choices\":[{\"message\":{\"content\":\"```bash\\nls -la\\n```\"}}]}";
    const n = L.extractCommand(sample, &out);
    try testing.expectEqualStrings("ls -la", out[0..n]);
}

test "extractCommand decodes the common JSON escapes" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    const sample = "{\"choices\":[{\"message\":{\"content\":\"echo \\\"hi\\\"\"}}]}";
    const n = L.extractCommand(sample, &out);
    try testing.expectEqualStrings("echo \"hi\"", out[0..n]);
}

test "extractCommand skips uncommon escapes (\\b, \\f) without leaking the escape code char" {
    const L = configure(.{});
    var out: [128]u8 = undefined;
    // `\b` (backspace): both \ and b must be skipped, output is "ab" not "abb".
    const sample_b = "{\"choices\":[{\"message\":{\"content\":\"a\\bb\"}}]}";
    try testing.expectEqualStrings("ab", out[0..L.extractCommand(sample_b, &out)]);
    // `\f` (form feed): both \ and f must be skipped.
    const sample_f = "{\"choices\":[{\"message\":{\"content\":\"a\\fb\"}}]}";
    try testing.expectEqualStrings("ab", out[0..L.extractCommand(sample_f, &out)]);
}

test "extractCommand skips \\uXXXX unicode escapes cleanly" {
    const L = configure(.{});
